const out = [];

for (const item of $input.all()) {
  const subject = item.json.subject || '';
  const awbMatch = subject.match(/(\d{12})/);

  if (!awbMatch) {
    out.push({
      json: {
        messageId: item.json.id || '',
        subject,
        sender: item.json.from?.emailAddress?.address || item.json.sender?.emailAddress?.address || '',
        receivedDateTime: item.json.receivedDateTime || new Date().toISOString(),
        errore: 'AWB non trovato nel subject'
      }
    });
    continue;
  }

  const awb = awbMatch[1];
  const binaries = item.binary || {};

  for (const [key, file] of Object.entries(binaries)) {
    const originalFileName = file.fileName || key || '';
    const mimeType = (file.mimeType || '').toLowerCase();

    const isPdf = /\.pdf$/i.test(originalFileName) || mimeType.includes('pdf');
    const validCiName = /^ci.*\.pdf$/i.test(originalFileName);

    if (!isPdf || !validCiName) continue;

    out.push({
      json: {
        messageId: item.json.id || '',
        subject,
        sender: item.json.from?.emailAddress?.address || item.json.sender?.emailAddress?.address || '',
        receivedDateTime: item.json.receivedDateTime || new Date().toISOString(),
        attachmentName: originalFileName,
        awb,
        errore: ''
      },
      binary: {
        data: file
      }
    });
  }
}

return out;

const rawText =
  $json.content?.parts?.[0]?.text ||
  $json.text ||
  $json.response ||
  $json.output ||
  '';

let parsed;

try {
  const cleaned = String(rawText)
    .replace(/```json\s*/i, '')
    .replace(/```/g, '')
    .trim();

  parsed = JSON.parse(cleaned);
} catch (error) {
  const source = $('Seleziona Allegati PDF').item.json;

  return {
    json: {
      awb: source.awb || '',
      invoice_number: '',
      invoice_date: '',
      supplier_name: '',
      hs_code: '',
      total_amount: '',
      currency: '',
      origin_country: '',
      date_today: new Date().toLocaleDateString('it-IT'),
      attachment_name: source.attachmentName || '',
      sender: source.sender || '',
      subject: source.subject || '',
      errore: 'JSON non valido restituito dal modello',
      raw_output: rawText
    },
    binary: $binary
  };
}

const invoiceNumber = parsed.invoice_number || '';
const invoiceDate = parsed.invoice_date || '';
const supplierName = parsed.supplier_name || '';
const hsCode = parsed.hs_code || '';
const currency = parsed.currency || '';
const originCountry = (parsed.origin_country || '').toUpperCase().trim();
const rawTotal = parsed.total_amount || '';

let totalAmount = rawTotal;
if (typeof rawTotal === 'string') {
  totalAmount = rawTotal
    .replace(/\s/g, '')
    .replace(/€/g, '')
    .replace(/\.(?=\d{3}(\D|$))/g, '')
    .replace(',', '.');
}

const totalNumeric = Number(totalAmount);
const source = $('Seleziona Allegati PDF').item.json;
const received = source.receivedDateTime || new Date().toISOString();
const dataRicezione = String(received).slice(0, 10);
const anno = dataRicezione.slice(0, 4);
const mese = dataRicezione.slice(5, 7);
const originalName = source.attachmentName || 'CI.pdf';

const invoiceSafe = invoiceNumber || 'senza-invoice';
const safeCiName = `${anno}${mese}_${invoiceSafe}_${originalName}`;
const safeDocxName = `Lettera_Sdoganamento_${source.awb || 'NOAWB'}_${invoiceSafe}.docx`;

let errore = '';

if (!source.awb || !/^\d{12}$/.test(source.awb)) {
  errore = 'AWB mancante o non valido';
} else if (!invoiceNumber) {
  errore = 'invoice_number mancante';
} else if (!supplierName) {
  errore = 'supplier_name mancante';
} else if (!hsCode) {
  errore = 'hs_code mancante';
} else if (!totalAmount || Number.isNaN(totalNumeric) || totalNumeric <= 0) {
  errore = 'total_amount non valido';
} else if (!currency) {
  errore = 'currency mancante';
} else if (!(originCountry === 'CHINA' || originCountry === 'MADE IN CHINA')) {
  errore = 'origin_country non confermato come CHINA';
}

const totalAmountDisplay = !Number.isNaN(totalNumeric)
  ? totalNumeric.toLocaleString('it-IT', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    })
  : '';

return {
  json: {
    awb: source.awb || '',
    invoice_number: invoiceNumber,
    invoice_date: invoiceDate,
    supplier_name: supplierName,
    hs_code: hsCode,
    total_amount: totalAmount,
    total_amount_display: totalAmountDisplay,
    currency,
    origin_country: originCountry,
    data_ricezione: dataRicezione,
    date_today: new Date().toLocaleDateString('it-IT'),
    anno,
    mese,
    attachment_name: originalName,
    saved_ci_name: safeCiName,
    saved_docx_name: safeDocxName,
    sender: source.sender || '',
    subject: source.subject || '',
    errore,
    raw_output: rawText
  },
  binary: $binary
};
